 <span class="line"></span>
</button>","custom_css":".menu-btn {
 display: block;
 background: transparent;
 border: 0 none;
 cursor: pointer;
 height: 60px;
 outline: none;
 position: relative;
 transition: background-color 0.2s ease-in-out;
 width: 40px;
}
.menu-btn .line,
.menu-btn .line::after,
.menu-btn .line::before {
 background-color: #FFF;
 display: block;
 height: 2px;
 width: 30px;
}
.menu-btn .line {
 margin: 0 auto;
 position: relative;
 top: 0;
 transition-delay: 0.2s;
 transition-duration: 0s;
}
.menu-btn .line::before, .menu-btn .line::after {
 content: "";
 position: absolute;
}
.menu-btn .line::before {
 margin-top: -8px;
 transition-delay: 0.2s, 0s;
 transition-duration: 0.2s;
 transition-property: margin, transform;
}
.menu-btn .line::after {
 margin-top: 8px;
 transition-delay: 0.2s, 0s;
 transition-duration: 0.2s;
 transition-property: margin, transform;
}
.menu-btn--is-active .line,
.menu-btn--is-active .line::after,
.menu-btn--is-active .line::before {
 background-color: #FFF;
}
.menu-btn--is-active .line {
 background-color: rgba(0, 0, 0, 0);
 transition-delay: 0.1s;
}
.menu-btn--is-active .line::before {
 margin-top: 0;
 transform: rotate(45deg);
 transition-delay: 0s, 0.2s;
}
.menu-btn--is-active .line::after {
 margin-top: 0;
 transform: rotate(-45deg);
 transition-delay: 0s, 0.2s;
}","hide_desktop":"hidden-desktop","_margin_mobile":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"_padding_mobile":{"unit":"px","top":"0","right":"0","bottom":"0","left":"10","isLinked":false}},"elements":[],"widgetType":"html"}],"isInner":true}],"isInner":false},{"id":"fb578fd","elType":"container","settings":{"flex_direction":"row","boxed_width":{"unit":"px","size":1300,"sizes":[]},"background_background":"classic","background_color":"#FFFFFF","content_width":"full","width_mobile":{"unit":"%","size":100,"sizes":[]},"flex_gap_mobile":{"column":"0","row":"0","isLinked":true,"unit":"px","size":0},"min_height_mobile":{"unit":"vh","size":100,"sizes":[]},"css_classes":"main-menu-medium flex-bet","hide_desktop":"hidden-desktop","custom_css":"body:not(.elementor-editor-active) selector {
