item.content:encoded:
.ovabrw-modern-product #booking_form .ovabrw-extra-services .ovabrw_resource .item .res-left .ovabrw-label-field
{
	font-family: "Poppins", Sans-serif;
	font-size: 15px;
	font-weight: 400;


}
.single .owl-carousel .owl-item img {
	display: block;
	width: 100%;
	height:200px !important;
	object-fit: cover;
	object-position: center;
}
.fancybox__toolbar {
	padding-top: 80px !important;
}
.fancybox__button--thumbs {
	display: none;
}
.fancybox__button--fullscreen {
	display: none;
}
.fancybox__button--slideshow {
	display: none;
}
.fancybox__button--zoom {
	display: none;
}
.terms-conditions {
	font-family: "Poppins", Sans-serif;
	font-size: 15px !important;
}
.ovabrw-price {
	font-family: var(--ovabrw-primary-font);
    font-size: 18px;
    font-style: normal;
    font-weight: 500;
    line-height: 34px;
    color: var(--ovabrw-primary-color);
}

.ovabrw-product-price {
	font-family: var(--ovabrw-primary-font);
    font-size: 18px;
    font-style: normal;
    font-weight: 500;
    line-height: 34px;
    color: var(--ovabrw-primary-color);
}
.elementor-196 .elementor-element.elementor-element-d7826f1 #place_order {
	color: white !important;
}
.elementor-195 .elementor-element.elementor-element-91d5fb3 .wc-proceed-to-checkout .button {
	color:white !important;
}
.elementor-195 .elementor-element.elementor-element-91d5fb3 .wc-proceed-to-checkout .button:hover {
	color:black !important;
}
.elementor-195 .elementor-element.elementor-element-91d5fb3 .actions button {
	background: transparent !important;
	border: solid 1px black;
	color: black !important;
	padding: 6px;
}
.woocommerce-form-login-toggle {
	display:none !important;
}

