","default_cat":"caracteristicas","category_not_in":["19","33","34","42"],"category_in":["45","46","47","48"],"posts_per_page":10},"elements":[],"widgetType":"ovabrw_search_ajax_hotel"}],"isInner":false},{"id":"6cd1cc4","elType":"container","settings":{"content_width":"full","margin":{"unit":"%","top":"0","right":"0","bottom":"0","left":"0","isLinked":true},"margin_tablet":{"unit":"%","top":"","right":"","bottom":"","left":"","isLinked":true},"margin_mobile":{"unit":"%","top":"","right":"","bottom":"","left":"","isLinked":true},"padding":{"unit":"%","top":"0","right":"4","bottom":"4","left":"4","isLinked":false},"padding_tablet":{"unit":"%","top":"","right":"","bottom":"","left":"","isLinked":true},"padding_mobile":{"unit":"%","top":"","right":"","bottom":"","left":"","isLinked":true}},"elements":[{"id":"1da7f86","elType":"widget","settings":{"content_width":"full","tabs":[{"tab_title":"Alquiler de coches Mercedes en Ibiza","tab_content":"<p><strong>Alquila coches Mercedes</strong> en Ibiza y disfruta de una experiencia de conducción excepcional. Nuestro servicio de <strong>alquiler de coches</strong> ofrece una gran variedad de <strong>vehículos alta gama</strong> que combinan estilo, comodidad y rendimiento.  Ofrecemos servicios de recogida en puntos estratégicos como el Puerto de Alicante, el Puerto de Ibiza y los Aeropuertos de ambas ciudades.</p><p>Nuestro equipo se encargará de que tu <strong>Mercedes</strong> esté listo para ti en el lugar y momento que lo necesites, permitiéndote comenzar tu viaje sin contratiempos y con el máximo confort. Disfruta de la libertad y el estilo desde el primer minuto con nuestro servicio premium de <strong>alquiler de coches de alta gama</strong>.</p>","_id":"b4e4076"},{"tab_title":"Beneficios de alquilar un coche de Mercedes en Ibiza","tab_content":"<p><strong>Confort y Estilo: </strong>Conduce un coche de alta gama y recorre Ibiza con el mayor confort posible. Todos nuestros Mercedes están equipados con interiores lujosos, características de seguridad avanzadas y un diseño exclusivo.</p><p><strong>Libertad y Flexibilidad</strong>: No dependas de los horarios de transporte público o de taxis. <strong>Alquila un Mercedes</strong> y disfruta de la libertad de explorar Ibiza a tu propio ritmo, desde las playas escondidas hasta los restaurantes más exclusivos.</p><p><strong>Presencia y Prestigio</strong>: Ibiza es sinónimo de exclusividad. Con un Mercedes de alquiler, tendrás la presencia que la isla merece. Destaca en cada lugar al que llegues, ya sea una fiesta en la playa, un restaurante exclusivo o una excursión por la isla.</p>","_id":"736645b"},{"tab_title":"Tipos de Mercedes disponibles para alquilar en Ibiza","tab_content":"<p><strong>Mercedes Clase V 220d Avantgarde Largo</strong>:</p><p>La opción ideal para quienes buscan <strong>espacio y comodidad sin compromisos</strong>, perfecto para <strong>grupos o familias</strong> que desean moverse con total confort.</p><p><strong>Mercedes GLC 220d 4MATIC</strong>:</p><p>Este SUV combina sofisticación con un <strong>rendimiento robusto</strong>, ideal para explorar Ibiza con toda la seguridad y estilo que necesitas.</p><p><strong>Mercedes GLC 220d 4MATIC Coupé AMG</strong>:</p><p>Una versión deportiva del GLC, que ofrece un <strong>diseño aerodinámico y una conducción dinámica</strong> para quienes buscan emociones fuertes.</p><p><strong>Mercedes Clase V 220D Largo</strong>:</p><p><strong>Amplio y confortable</strong>, pensado para aquellos que necesitan un vehículo espacioso con toda la comodidad y tecnología característica de Mercedes, <strong>perfecto para traslados en grupo</strong>.</p>","_id":"30194a1"},{"tab_title":"¿Por qué alquilar coche en Ibiza?","tab_content":"<p>Recorrer Ibiza en un Mercedes no solo es una cuestión de transporte, es una experiencia.</p><p>Conduce por las carreteras costeras y disfruta de los atardeceres más impresionantes, accede con facilidad a los lugares más exclusivos de la isla y haz de cada momento algo especial.</p>","_id":"c0e0f56"}],"selected_icon":{"value":"fas fa-chevron-down","library":"fa-solid"},"title_color":"#1C1F1E","tab_active_color":"#000000","title_typography_typography":"custom","title_typography_font_family":"Inter","title_typography_font_size":{"unit":"px","size":22,"sizes":[]},"title_typography_font_weight":"500","icon_space":{"unit":"px","size":0,"sizes":[]},"content_color":"#000000","content_typography_typography":"custom","content_typography_font_family":"Inter","content_typography_font_size":{"unit":"px","size":16,"sizes":[]},"content_typography_font_weight":"300","content_typography_line_height":{"unit":"em","size":1.2,"sizes":[]},"_margin":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"_background_color_stop_tablet":{"unit":"%","size":"","sizes":[]},"_background_color_stop_mobile":{"unit":"%","size":"","sizes":[]},"_background_color_b_stop_tablet":{"unit":"%","size":"","sizes":[]},"_background_color_b_stop_mobile":{"unit":"%","size":"","sizes":[]},"_background_gradient_angle_tablet":{"unit":"deg","size":"","sizes":[]},"_background_gradient_angle_mobile":{"unit":"deg","size":"","sizes":[]},"_background_hover_color_stop_tablet":{"unit":"%","size":"","sizes":[]},"_background_hover_color_stop_mobile":{"unit":"%","size":"","sizes":[]},"_background_hover_color_b_stop_tablet":{"unit":"%","size":"","sizes":[]},"_background_hover_color_b_stop_mobile":{"unit":"%","size":"","sizes":[]},"_background_hover_gradient_angle_tablet":{"unit":"deg","size":"","sizes":[]},"_background_hover_gradient_angle_mobile":{"unit":"deg","size":"","sizes":[]}},"elements":[],"widgetType":"accordion"}],"isInner":false}]

